@startuml
class Library {
}

class RegisteredUser {
  +securityDeposit : float
}

class BorrowableItem {
  +libraryCode : string
  +location : string
}

class Book extends BorrowableItem {
  +publisher : string
}

class MagazineIssue extends BorrowableItem {
  +publicationDate : date
  +publisher : string
}

class MusicCD extends BorrowableItem {
  +publisher : string
  +artist : string
}

class VHSFilm extends BorrowableItem {
  +duration : int
  +publisher : string
}

class DVDFilm extends BorrowableItem {
  +duration : int
  +publisher : string
}

class Author {
}

class Actor {
}

class Request {
}

Library "1" *-- "*" RegisteredUser : has
Library "1" *-- "*" BorrowableItem : has
RegisteredUser "0..1" -- "0..3" BorrowableItem : borrows
Book "1..*" -- "1..*" Author : written by
VHSFilm "1..*" -- "1..*" Actor : features
DVDFilm "1..*" -- "1..*" Actor : features
RegisteredUser "0..*" -- "0..*" Library : sends request to
Request ..> BorrowableItem : for
@enduml

